using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem / GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_SingleItem_TotalReflectsPrice()
    {
        _cart.AddItem("SKU1", 9.99m, 1);
        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesCorrectly()
    {
        _cart.AddItem("SKU1", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 10.00m, 1);
        _cart.AddItem("B", 20.00m, 2);
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_ReducesTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU2", 5.00m, 2);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_RemovesSameSkuAddedMultipleTimes()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 10.00m, 2);
        _cart.RemoveItem("SKU1");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- ApplyPromoCode ---

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        bool applied = _cart.ApplyPromoCode("SAVE10");
        Assert.IsTrue(applied);
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        bool applied = _cart.ApplyPromoCode("BOGUS");
        Assert.IsFalse(applied);
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_DiscountDoesNotGoBelowZero()
    {
        _cart.AddItem("SKU1", 5.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        Assert.IsTrue(_cart.GetTotal() >= 0m);
    }
}

